CREATE TABLE s_payment_plans(id TEXT PRIMARY KEY,bill_id TEXT NOT NULL REFERENCES s_bills(id),revision TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('paused','active','stopped','completed')),stop_reason TEXT,source_system TEXT,source_reference TEXT,approved_by TEXT NOT NULL,approved_operator_id TEXT NOT NULL,approved_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE UNIQUE INDEX s_payment_plan_one_live ON s_payment_plans(bill_id) WHERE status IN('paused','active');
CREATE TABLE s_payment_plan_versions(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES s_payment_plans(id),bill_revision TEXT NOT NULL,start_date TEXT NOT NULL,balance_cents INTEGER NOT NULL CHECK(balance_cents>0),reason TEXT NOT NULL,approved_by TEXT NOT NULL,approved_at TEXT NOT NULL);
CREATE TABLE s_payment_plan_installments(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES s_payment_plans(id),revision TEXT NOT NULL REFERENCES s_payment_plan_versions(id),position INTEGER NOT NULL,due_date TEXT NOT NULL,cents INTEGER NOT NULL CHECK(cents>0),UNIQUE(revision,position));
CREATE TABLE s_payment_plan_setups(id TEXT PRIMARY KEY,request_key TEXT NOT NULL UNIQUE,request_json TEXT NOT NULL,plan_id TEXT NOT NULL REFERENCES s_payment_plans(id),revision TEXT NOT NULL REFERENCES s_payment_plan_versions(id),client_email TEXT NOT NULL,config_id TEXT NOT NULL REFERENCES s_stripe_config(id),session_id TEXT UNIQUE,status TEXT NOT NULL CHECK(status IN('creating','open','uncertain','consumed')),created_at TEXT NOT NULL);
CREATE TABLE s_payment_plan_consents(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES s_payment_plans(id),revision TEXT NOT NULL REFERENCES s_payment_plan_versions(id),setup_id TEXT NOT NULL UNIQUE REFERENCES s_payment_plan_setups(id),client_email TEXT NOT NULL,config_id TEXT NOT NULL REFERENCES s_stripe_config(id),customer_id TEXT NOT NULL,payment_method_id TEXT NOT NULL,mandate_id TEXT,granted_at TEXT NOT NULL);
CREATE UNIQUE INDEX s_payment_plan_one_consent ON s_payment_plan_consents(plan_id,revision);
CREATE TABLE s_payment_plan_attempts(checkout_id TEXT PRIMARY KEY REFERENCES s_stripe_checkouts(id),installment_id TEXT NOT NULL UNIQUE REFERENCES s_payment_plan_installments(id),consent_id TEXT NOT NULL REFERENCES s_payment_plan_consents(id),created_at TEXT NOT NULL);
CREATE TABLE s_payment_plan_events(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES s_payment_plans(id),revision TEXT NOT NULL,kind TEXT NOT NULL,detail TEXT NOT NULL,actor TEXT NOT NULL,at TEXT NOT NULL,task_id TEXT REFERENCES s_tasks(id));
CREATE TRIGGER s_payment_plan_versions_no_update BEFORE UPDATE ON s_payment_plan_versions BEGIN SELECT RAISE(ABORT,'plan versions are immutable'); END;
CREATE TRIGGER s_payment_plan_versions_no_delete BEFORE DELETE ON s_payment_plan_versions BEGIN SELECT RAISE(ABORT,'plan versions are immutable'); END;
CREATE TRIGGER s_payment_plan_installments_no_update BEFORE UPDATE ON s_payment_plan_installments BEGIN SELECT RAISE(ABORT,'plan installments are immutable'); END;
CREATE TRIGGER s_payment_plan_installments_no_delete BEFORE DELETE ON s_payment_plan_installments BEGIN SELECT RAISE(ABORT,'plan installments are immutable'); END;
CREATE TRIGGER s_payment_plan_consents_no_update BEFORE UPDATE ON s_payment_plan_consents BEGIN SELECT RAISE(ABORT,'plan consent is immutable'); END;
CREATE TRIGGER s_payment_plan_consents_no_delete BEFORE DELETE ON s_payment_plan_consents BEGIN SELECT RAISE(ABORT,'plan consent is immutable'); END;
CREATE TRIGGER s_payment_plan_attempts_no_update BEFORE UPDATE ON s_payment_plan_attempts BEGIN SELECT RAISE(ABORT,'plan attempts are immutable'); END;
CREATE TRIGGER s_payment_plan_attempts_no_delete BEFORE DELETE ON s_payment_plan_attempts BEGIN SELECT RAISE(ABORT,'plan attempts are immutable'); END;
CREATE TRIGGER s_payment_plan_events_no_update BEFORE UPDATE ON s_payment_plan_events BEGIN SELECT RAISE(ABORT,'plan events are immutable'); END;
CREATE TRIGGER s_payment_plan_events_no_delete BEFORE DELETE ON s_payment_plan_events BEGIN SELECT RAISE(ABORT,'plan events are immutable'); END;
